package com.greenocean.backend;
import com.greenocean.backend.trust.IncidentSignals;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.junit.jupiter.api.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.trust.enabled=true","greenocean.operations.signal-worker-enabled=true","greenocean.operations.signal-threshold=1","greenocean.operations.signal-sweep-ms=3600000","greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa","greenocean.clinic.reputation-enabled=true","greenocean.clinic.public-reputation-enabled=true","greenocean.clinic.reputation-keys=reputation-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.reputation-current-key=reputation-qa"})@AutoConfigureMockMvc@ActiveProfiles("test")@Transactional
class PhaseQ3SignalTest extends PhaseP4Fixtures {
 @Autowired IncidentSignals signals;
 @Test void repeatedSourceRefundFailureCreatesOneUnassignedMetadataOnlyIncident(){db.update("INSERT INTO clinic_refunds(appointment_id,amount_units,state,reason,initiate_by) VALUES(?,1,'REFUND_REQUESTED','Synthetic isolated overdue record; no real funds',CURRENT_TIMESTAMP-INTERVAL '1 minute')",appointment);signals.observe();signals.observe();var rows=db.queryForList("SELECT owner_id,created_by,evidence_reference FROM operation_incidents WHERE domain='FINANCE' AND kind='REFUND_DELAY'");assertThat(rows).hasSize(1);assertThat(rows.getFirst()).containsEntry("owner_id",null).containsEntry("created_by",null).containsEntry("evidence_reference","SIGNAL:overdue-unconfirmed-refunds");assertThat(rows.toString()).doesNotContain(appointment.toString(),learner.id().toString(),"real funds");}
 @Test void emailRetrySignalNeverCopiesRecipientOrPayload(){db.update("INSERT INTO email_outbox(recipient,template_key,payload,status,attempts,expires_at) VALUES('synthetic-private@example.test','synthetic-q3','{\"encrypted\":\"SYNTHETIC_PRIVATE_PAYLOAD\"}'::jsonb,'FAILED',3,CURRENT_TIMESTAMP+INTERVAL '1 hour')");signals.observe();String rows=db.queryForList("SELECT domain,kind,severity,evidence_reference FROM operation_incidents WHERE kind='EMAIL_OUTAGE'").toString();assertThat(rows).contains("EMAIL_OUTAGE","SIGNAL:email-transport-retries").doesNotContain("synthetic-private","SYNTHETIC_PRIVATE_PAYLOAD");}
}
